const liveAuthTokenNamesOfUser = `-- name: LiveAuthTokenNamesOfUser :many
SELECT name FROM auth_tokens_named WHERE username = $1 AND revoked_at IS NULL ORDER BY name
`

// LiveAuthTokenNamesOfUser is what a name's removal revokes.
func (q *Queries) LiveAuthTokenNamesOfUser(ctx context.Context, username string) ([]string, error) {
	rows, err := q.db.QueryContext(ctx, liveAuthTokenNamesOfUser, username)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []string
	for rows.Next() {
		var name string
		if err := rows.Scan(&name); err != nil {
			return nil, err
		}
		items = append(items, name)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

