const touchUser = `-- name: TouchUser :one
INSERT INTO users (username, principal_id, created_at, last_seen) VALUES ($1, $2, $3, $3)
ON CONFLICT (username) DO UPDATE SET last_seen = excluded.last_seen
RETURNING username, principal_id, password_hash, created_at, last_seen, disabled_at, default_group
`

type TouchUserParams struct {
	Username    string
	PrincipalID ids.ID
	At          time.Time
}

// TouchUser records a name seen on the wire: a new name becomes a member
// with no password, a known one gets its last-seen stamp.
func (q *Queries) TouchUser(ctx context.Context, arg TouchUserParams) (User, error) {
	row := q.db.QueryRowContext(ctx, touchUser, arg.Username, arg.PrincipalID, arg.At)
	var i User
	err := row.Scan(
		&i.Username,
		&i.PrincipalID,
		&i.PasswordHash,
		&i.CreatedAt,
		&i.LastSeen,
		&i.DisabledAt,
		&i.DefaultGroup,
	)
	return i, err
}

