const usersAll = `-- name: UsersAll :many
SELECT username, principal_id, password_hash, created_at, last_seen, disabled_at, default_group FROM users ORDER BY username
`

func (q *Queries) UsersAll(ctx context.Context) ([]User, error) {
	rows, err := q.db.QueryContext(ctx, usersAll)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []User
	for rows.Next() {
		var i User
		if err := rows.Scan(
			&i.Username,
			&i.PrincipalID,
			&i.PasswordHash,
			&i.CreatedAt,
			&i.LastSeen,
			&i.DisabledAt,
			&i.DefaultGroup,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const usersSignedIn = `-- name: UsersSignedIn :many
SELECT username FROM sessions_named
UNION SELECT username FROM delegations_named
UNION SELECT username FROM auth_tokens_named WHERE last_used IS NOT NULL
`

// UsersSignedIn is every name that has ever signed in: it holds a session,
// an agent connection, or a personal token that has been used.
func (q *Queries) UsersSignedIn(ctx context.Context) ([]string, error) {
	rows, err := q.db.QueryContext(ctx, usersSignedIn)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []string
	for rows.Next() {
		var username string
		if err := rows.Scan(&username); err != nil {
			return nil, err
		}
		items = append(items, username)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
